-- Store Short Content and Long Content in Supabase Database
-- for ALL 16 EQ Competencies (public.eq_competency_guides)
-- AND ALL learning episodes (public.learning_content.short_content / long_content)

-- ─── 1. Competency-Level First-Principles Reading Guides ──────────────────────
CREATE TABLE IF NOT EXISTS public.eq_competency_guides (
  competency_key TEXT PRIMARY KEY,
  sequence_order INT NOT NULL,
  domain_key TEXT NOT NULL,
  domain_label TEXT NOT NULL,
  title TEXT NOT NULL,
  short_content TEXT NOT NULL,
  what_it_is TEXT NOT NULL,
  why_it_matters TEXT NOT NULL,
  how_to_measure JSONB NOT NULL DEFAULT '[]'::jsonb,
  long_content TEXT NOT NULL,
  practice_prompt TEXT NOT NULL,
  estimated_read_minutes INT NOT NULL DEFAULT 3,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.eq_competency_guides ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "eq_competency_guides_select_authenticated" ON public.eq_competency_guides;
CREATE POLICY "eq_competency_guides_select_authenticated"
  ON public.eq_competency_guides FOR SELECT TO authenticated USING (true);

INSERT INTO public.eq_competency_guides (
  competency_key, sequence_order, domain_key, domain_label, title,
  short_content, what_it_is, why_it_matters, how_to_measure,
  long_content, practice_prompt, estimated_read_minutes
) VALUES
(
  'SELF_AWARENESS', 1, 'SELF_AWARENESS_DOMAIN', 'Self-Awareness', 'Emotional Self-Awareness',
  'Detecting internal emotional signals in real time and distinguishing felt sensations from stories or assumptions before they dictate behavior.',
  'From first principles, an emotion is a rapid physiological and cognitive signal generated by the nervous system to highlight something you value or perceive as a threat. Emotional self-awareness is interoceptive accuracy plus granular labeling: noticing tightened shoulders, rising heart rate, or narrowing attention, naming the exact state ("defensive", "overloaded", "disappointed") rather than vague labels like "stressed", and tracing the trigger that caused it.',
  'Without real-time signal detection, emotion runs on autopilot—turning constructive feedback into defensiveness or fatigue into cynicism. High self-awareness inserts cognitive separation between stimulus and response, improving decision quality under pressure and aligning daily actions with your actual values.',
  '["Affect granularity: Can you name 3+ distinct emotions you experienced today beyond \"good\" or \"bad\"?","Detection latency: How quickly do you notice irritation or anxiety—during the meeting, or two hours afterward?","Trigger clarity & feedback calibration: Do you recognize your recurring blind spots, and does your self-assessment match peer feedback?"]'::jsonb,
  'Emotional self-awareness is the foundation on which every other Emotional Intelligence competency rests. Neurologically, before you consciously decide how to speak in a tense meeting, your autonomic nervous system has already shifted blood flow, breathing cadence, and threat vigilance. Labeling an emotion accurately ("I notice apprehension about the timeline" rather than "everything is falling apart") activates prefrontal appraisal networks and reduces limbic reactivity. Practically, high performers treat emotional data like instrumentation on a cockpit dashboard: neither ignored nor obeyed blindly, but read early to diagnose values, boundaries, and cognitive bias before acting.',
  'Before high-stakes meetings today, take 20 seconds to check bodily tension, name the primary emotion present, and state one objective fact separating the feeling from action.',
  4
),
(
  'EMOTIONAL_BALANCE', 2, 'SELF_MANAGEMENT_DOMAIN', 'Self-Management', 'Emotional Balance',
  'Modulating intense impulses and recovery speed under stress so disruptive emotions inform judgment without hijacking conduct.',
  'From first principles, emotional balance is not emotional suppression—it is autonomic and cognitive regulation. When the amygdala triggers an acute threat response, executive working memory temporarily narrows. Emotional balance uses physiological resets (slow exhale breathing, visual widening) and cognitive reappraisal to restore prefrontal control so you choose a proportional, values-aligned response.',
  'In organizations, a leader''s dysregulated nervous system is contagious: one reactive outburst erodes psychological safety built over months. Conversely, composure under ambiguity keeps teams analytical, prevents avoidable escalation, and protects personal energy from chronic burnout.',
  '["Recovery half-life: After a frustrating setback or tense email, how many minutes does it take to return to baseline focus?","Impulse gap: Frequency of sending sharp replies or interrupting versus pausing 6 seconds before responding.","Composure consistency: Stability of tone and fairness across high-workload vs. calm weeks."]'::jsonb,
  'Suppressing frustration does not remove it; unexamined adrenaline merely leaks out later as cynicism, micromanagement, or cognitive fatigue. Emotional balance replaces suppression with state-shifting mechanics: extending your exhale shifts vagal tone down within seconds, while asking "What else could explain this behavior?" breaks tunnel vision. Over time, training emotional balance shrinks your recovery half-life after friction, turning acute pressure into calm decisiveness that stabilizes the entire room around you.',
  'When you feel a surge of urgency or frustration, wait one full breath cycle with a longer exhale before typing or speaking.',
  4
),
(
  'POSITIVE_OUTLOOK', 3, 'SELF_MANAGEMENT_DOMAIN', 'Self-Management', 'Positive Outlook',
  'Interpreting setbacks as specific, temporary, and solvable—preserving agency and constructive energy without naive denial.',
  'From first principles, positive outlook is an explanatory style rooted in realistic agency. Rather than ignoring risks ("toxic positivity"), it separates facts from catastrophic permanence: when something fails, you frame the setback as bounded in scope ("this rollout plan had a gap") and reversible through targeted action, rather than permanent or personal.',
  'Chronic threat framing constricts attention and creates learned helplessness across teams. Realistic optimism keeps problem-solving bandwidth open during setbacks, sustains effort across long innovation cycles, and models resilience when projects hit unexpected friction.',
  '["Explanatory framing: After a loss, do your first statements focus on permanent flaws or adjustable variables?","Opportunity spotting: Ratio of actionable next experiments proposed per post-mortem or roadblock.","Energy steadiness: Ability to rally team focus after a missed target without minimizing reality."]'::jsonb,
  'Positive outlook is fundamentally a causal-attribution habit. Under pressure, brains default to threat generalization ("this always goes wrong"), which shuts down exploratory thinking. By intentionally scoping failure along three axes—specific rather than global, temporary rather than permanent, and behavioral rather than character-based—you keep working memory focused on what can be changed next. Teams led with realistic optimism confront brutal truths earlier because setbacks signal course correction rather than defeat.',
  'Take one current frustration and rewrite it into: (1) the exact bounded problem, (2) one controllable lever, and (3) your next 24-hour experiment.',
  4
),
(
  'ADAPTABILITY', 4, 'SELF_MANAGEMENT_DOMAIN', 'Self-Management', 'Adaptability',
  'Releasing outdated plans smoothly when reality shifts, juggling competing demands while staying anchored on core outcomes.',
  'From first principles, adaptability is low attachment to sunk costs paired with rapid mental model updating. Humans naturally cling to initial plans because rewriting expectations consumes cognitive effort. Adaptability treats strategy as a living hypothesis: as new constraints or customer feedback arrive, you recalibrate tactics without emotional paralysis.',
  'Markets, priorities, and dependencies shift faster than annual plans. Rigid contributors fight reality and create organizational drag; adaptable professionals absorb ambiguity cleanly, re-prioritize without drama, and turn sudden changes into competitive advantage.',
  '["Pivot friction: Time spent defending an obsolete plan versus re-scoping after new data arrives.","Multitasking composure: Maintaining quality across shifting priorities without thrashing.","Experiment willingness: Frequency of testing unfamiliar tools, workflows, or perspectives in the past quarter."]'::jsonb,
  'Most resistance to change is ego attachment to yesterday''s plan disguised as analytical rigor. True adaptability distinguishes goals from mechanisms: hold the target outcome steady while holding tactics lightly. When new information invalidates an assumption, adaptable leaders celebrate catching the signal early, retire legacy workflows without drama, and reallocate attention rapidly toward higher-leverage paths.',
  'Identify one assumption or routine you are holding onto out of habit rather than current evidence, and test an alternative approach this week.',
  4
),
(
  'ACHIEVEMENT_ORIENTATION', 5, 'SELF_MANAGEMENT_DOMAIN', 'Self-Management', 'Achievement Orientation',
  'Setting clear, measurable standards of excellence and iterating against feedback rather than settling for compliance or busyness.',
  'From first principles, achievement orientation is an internal feedback loop comparing current output against an explicit bar of excellence. It combines calibrated stretch goals, calculated risk-taking, and relentless curiosity about how to cut waste and raise quality—driven by intrinsic mastery rather than mere external approval.',
  'Activity is not impact. Organizations drift toward mediocrity when "good enough" goes unchallenged. High achievement orientation lifts team velocity and craftsmanship, keeps projects anchored to measurable outcomes, and turns routine execution into compounding skill.',
  '["Outcome clarity: Percentage of your weekly priorities tied to concrete, verifiable results rather than vague activity.","Feedback appetite: How proactively you seek critique on early drafts before final delivery.","Continuous improvement: Measurable efficiency, quality, or speed gains shipped across recent cycles."]'::jsonb,
  'Achievement orientation closes the gap between motion and measurable progress. Instead of measuring success by hours spent or checklists ticked, high performers define explicit quality criteria upfront, solicit disconfirming feedback while drafts are still malleable, and systematically strip friction out of repeated workflows. Excellence becomes a compounding daily standard rather than last-minute heroics.',
  'Pick your most important deliverable this week and define what "10/10 excellence" looks like in concrete metrics before you start executing.',
  4
),
(
  'EMPATHY', 6, 'SOCIAL_AWARENESS_DOMAIN', 'Social Awareness', 'Empathy',
  'Accurately reading another person''s unspoken emotional state, incentives, and perspective—and validating them before problem-solving.',
  'From first principles, empathy combines two distinct circuits: affective resonance (sensing what someone else feels) and cognitive perspective-taking (modeling why their situation makes sense from their vantage point and constraints). True empathy requires suspending your own rebuttal long enough to listen to tone, pacing, posture, and underlying needs.',
  'Most workplace misalignment is not intellectual—it is unacknowledged emotion or unheard stakes. When stakeholders feel accurately understood, resistance drops sharply, root causes surface faster, and collaboration replaces defensive posturing.',
  '["Accuracy of understanding: When you summarize someone else''s view back to them, how often do they say \"Yes, exactly\"?","Listening ratio: Balance between open inquiry questions and premature advice-giving in difficult conversations.","Cross-functional trust: Whether peers from different functions seek you out when tension is high."]'::jsonb,
  'Empathy is often misunderstood as softness or endless agreement. In reality, it is high-bandwidth situational intelligence: accurately decoding what another human perceives, fears, and optimizes for. You do not have to endorse someone''s conclusion to make them feel deeply heard. Once a colleague recognizes that you understand their real constraint—not a strawman of it—defensiveness drops and joint problem-solving accelerates immediately.',
  'In your next conversation where someone disagrees, spend two full minutes reflecting their core concern and emotion accurately before offering your view.',
  4
),
(
  'ORGANIZATIONAL_AWARENESS', 7, 'SOCIAL_AWARENESS_DOMAIN', 'Social Awareness', 'Organizational Awareness',
  'Mapping informal power networks, unspoken cultural norms, and cross-team incentives so initiatives land smoothly across the system.',
  'From first principles, an organization is a living network of competing incentives, formal authority, and informal trust coalitions—not just a static org chart. Organizational awareness is systems-level social perception: seeing how decisions ripple across departments, whose buy-in actually unblocks execution, and what unwritten rules govern how work really gets done.',
  'Great ideas routinely stall because sponsors miss invisible political constraints or misread organizational readiness. High organizational awareness prevents blind-siding stakeholders, aligns proposals with leadership priorities, and accelerates enterprise execution.',
  '["Stakeholder mapping: Can you accurately predict who gains, who loses, and who has veto power on a proposal before pitching it?","Cultural fluency: Understanding implicit communication norms across teams, levels, and geographies.","Decision velocity: Fewer stalled initiatives caused by late-stage stakeholder surprises."]'::jsonb,
  'Every organization runs on two maps simultaneously: the formal reporting chart and the informal ledger of trust, budget anxiety, status, and unwritten taboos. Projects fail rarely from weak logic alone—they fail when advocates ignore downstream burdens placed on adjacent teams. Organizational awareness means diagnosing incentives early, reading subtle hesitations in cross-functional reviews, and sequencing buy-in thoughtfully.',
  'Before advancing your next cross-team idea, list the top 4 stakeholders outside your team, their primary KPI pressures, and what success looks like to each.',
  4
),
(
  'INFLUENCE', 8, 'RELATIONSHIP_MANAGEMENT_DOMAIN', 'Relationship Management', 'Influence',
  'Building genuine commitment around shared outcomes by framing ideas around others'' priorities, values, and evidence rather than authority.',
  'From first principles, authority can compel short-term compliance, whereas influence shifts genuine belief and voluntary commitment. Effective influence starts from the audience''s world—anchoring arguments in what they already care about, anticipating skepticism honestly, building pre-meeting coalitions, and presenting crisp evidence paired with resonant narrative.',
  'In matrixed enterprises, you rarely control every resource you depend on. Influence lets individual contributors and leaders alike align cross-functional teams, secure executive sponsorship, and move decisions forward without relying on escalation.',
  '["Coalition strength: How often key stakeholders champion your ideas when you are not in the room.","Frame adaptation: Ability to tailor the exact same proposal meaningfully for engineering, finance, and frontline teams.","Commitment quality: Sustained follow-through after agreement rather than quiet post-meeting drag."]'::jsonb,
  'Coercion buys temporary compliance accompanied by passive resistance. Lasting influence aligns incentives and honors the listener''s autonomy. Rather than repeating your own rationale louder, high-influence leaders translate their proposal into each stakeholder''s native language—risk reduction for legal, velocity for engineering, predictability for finance—and earn early social proof before major meetings.',
  'Before your next pitch, write the opening sentence entirely from your listener''s highest-priority problem rather than your solution.',
  4
),
(
  'COACH_MENTOR', 9, 'RELATIONSHIP_MANAGEMENT_DOMAIN', 'Relationship Management', 'Coach & Mentor',
  'Multiplying capability in others through candid, actionable feedback, stretch assignments, and reflective questions rather than rescuing them.',
  'From first principles, fixing someone''s problem builds dependency; coaching builds capability. Coaching blends high care with clear standards: diagnosing an individual''s specific growth edge, asking catalytic questions that unlock their own thinking, giving timely behavior-focused feedback, and delegating stretch work with safe guardrails.',
  'A manager''s output scales linearly; a coach''s output scales exponentially through the people they develop. Organizations with strong coaching cultures retain top talent longer, build deeper leadership benches, and accelerate skill transfer.',
  '["Question-to-directive ratio: In 1:1s, do you help teammates arrive at answers or jump straight to instructions?","Feedback specificity: Delivery of timely, observable behavior-impact feedback paired with clear support.","Promotion & growth rate: Tangible skill progression or ownership expansion among people you mentor."]'::jsonb,
  'Rescuing an overwhelmed direct report feels helpful in the moment, yet teaches helplessness and bottlenecks every hard decision back onto your desk. True coaching resists the urge to give immediate answers when a guided question can expand the other person''s pattern recognition. Pairing candid behavioral feedback with stretch ownership converts individual effort into enduring organizational bench strength.',
  'When a teammate brings you a problem today, ask "What options have you weighed, and which trade-off feels sharpest?" before sharing your recommendation.',
  4
),
(
  'CONFLICT_MANAGEMENT', 10, 'RELATIONSHIP_MANAGEMENT_DOMAIN', 'Relationship Management', 'Conflict Management',
  'Surfacing disagreements early, separating people from positions, and converting friction into durable, higher-quality agreements.',
  'From first principles, conflict is simply surfaced incompatibility between goals, perspectives, or scarce resources—it is healthy fuel if channeled properly and toxic if avoided or personalized. Conflict management surfaces underlying interests beneath rigid positions, keeps emotional temperature below threat threshold, and designs mutually workable resolutions.',
  'Avoiding hard conversations creates artificial harmony and silent execution failure; aggressive confrontation destroys trust. Mastering conflict enables high-candor debate followed by clean alignment.',
  '["Time-to-surface: Addressing recurring friction within days rather than letting resentment compound for months.","Post-conflict trust: Do working relationships emerge clearer and stronger after tough disagreements?","Root resolution rate: Fewer recurring identical disputes across sprints or quarters."]'::jsonb,
  'High-performing teams do not avoid conflict—they keep conflict focused on ideas, constraints, and shared quality rather than personal identity. Unspoken disagreements drive costly rework and corridor cynicism. Skilled conflict managers surface tension directly, validate legitimate stakes on all sides, dig underneath rigid opening demands to find shared interests, and close with explicit commitments.',
  'Name one avoided tension respectfully today using: "Here is what I observe, here is the shared goal I care about, and here is what I want to understand from you."',
  4
),
(
  'TEAMWORK', 11, 'RELATIONSHIP_MANAGEMENT_DOMAIN', 'Relationship Management', 'Teamwork',
  'Creating shared ownership, transparent communication, and psychological safety so the collective outperforms individual heroics.',
  'From first principles, high-performing teamwork relies on trust density and explicit coordination loops. Individual talent plateaus without shared mental models, mutual accountability, generous credit-sharing, and willingness to step across strict job boundaries when collective delivery is at risk.',
  'Complex enterprise outcomes never fit inside a single role. Strong teamwork reduces handoff defects, encourages early risk-flagging before problems compound, and creates belonging that sustains peak effort.',
  '["Help velocity: Speed and willingness with which team members assist blocked peers.","Candid risk sharing: Whether teammates flag delays or mistakes early instead of hiding them.","Shared credit vs. blame: Recognition of cross-functional contributors alongside personal wins."]'::jsonb,
  'Individual brilliance fails whenever inter-team handoffs break down. Great teamwork lowers interpersonal friction: expectations are crystal clear, credit flows generously outward, blockers are raised early without fear of blame, and teammates prioritize the scoreboard over personal turf.',
  'Proactively ask one colleague today where their sharpest bottleneck sits and offer a concrete 15-minute unblock or handoff improvement.',
  4
),
(
  'INSPIRATIONAL_LEADERSHIP', 12, 'RELATIONSHIP_MANAGEMENT_DOMAIN', 'Relationship Management', 'Inspirational Leadership',
  'Connecting daily work to a compelling purpose while modeling integrity, steadiness, and conviction so people bring their best voluntarily.',
  'From first principles, people commit deeply when effort feels meaningful, achievable, and led with integrity. Inspirational leadership unifies all prior EQ competencies: clarity of purpose (why this matters), emotional resonance (making people feel seen), and behavioral consistency (living the values when it costs something).',
  'Compensation buys attendance; purpose and trust unlock discretionary effort, creativity, and resilience during transformation. Leaders who embody this raise engagement, anchor culture, and leave every team stronger than they found it.',
  '["Purpose clarity: Can every person on your team explain why their current project matters to users or the business?","Trust & walk-the-talk ratio: Alignment between stated values and tough resource/people decisions.","Momentum under uncertainty: Team energy and alignment during high-change initiatives."]'::jsonb,
  'Inspirational leadership is not volume or theatrics; it is moral clarity combined with human presence. People follow leaders who articulate a future worth building, demonstrate unwavering fairness under pressure, acknowledge fear honestly without spreading panic, and invest belief in people before they fully believe in themselves.',
  'In your next team touchpoint, connect one routine task explicitly to the real human or customer outcome it makes possible.',
  4
),
(
  'SELF_REGULATION', 2, 'SELF_REGULATION_DOMAIN', 'Self-Regulation', 'Self-Regulation',
  'Creating a deliberate pause between emotional impulse and outward action so your response aligns with long-term values.',
  'Self-regulation governs how you steer attention, impulses, and physiological arousal once an emotional wave hits. Rather than suppressing emotion, it widens the pause between trigger and reaction so deliberate reasoning catches up.',
  'Most regretted words and choices happen in a 5-second impulse window. Training self-regulation protects relationships, steadies daily mood, and lowers chronic stress.',
  '["Pause frequency before reacting in tense moments.","Recovery time back to calm concentration.","Consistency of habits during stressful weeks."]'::jsonb,
  'Between an emotional trigger and an action lies a trainable choice window. Self-regulation strengthens that pause through mindful breathing, reframing assumptions, and delaying high-heat replies until executive clarity returns.',
  'Practice a 4-second inhale / 6-second exhale reset whenever your chest feels tight today.',
  3
),
(
  'SOCIAL_SKILLS', 4, 'SOCIAL_SKILLS_DOMAIN', 'Social Skills', 'Social Skills',
  'Communicating clearly, warmly, and constructively—making honest dialogue feel safe and actionable.',
  'Social skills translate internal awareness and empathy into spoken clarity: active listening, non-defensive framing, direct requests, and calibrated tone.',
  'Strong relationships depend on words that land cleanly without triggering unnecessary threat or confusion.',
  '["Clarity of agreements reached after conversations.","Absence of lingering unspoken resentment.","Confidence navigating sensitive topics directly."]'::jsonb,
  'Great communication balances candor and warmth. Choosing "I observe / I need" language over blame keeps listeners receptive so honest feedback turns into shared alignment.',
  'Turn one vague frustration into a clear, respectful request stating observation + need.',
  3
),
(
  'MOTIVATION', 5, 'MOTIVATION_DOMAIN', 'Motivation', 'Intrinsic Motivation',
  'Connecting daily discipline to deeper personal meaning so persistence outlasts temporary mood swings.',
  'Intrinsic motivation runs on autonomy, mastery, and purpose rather than short-term willpower alone. Knowing why a goal matters makes friction tolerable.',
  'Willpower depletes rapidly under fatigue; purpose-anchored motivation sustains deep learning and consistent execution.',
  '["Clarity on why top goals matter personally.","Follow-through after early novelty wears off.","Curiosity when facing unfamiliar challenges."]'::jsonb,
  'External rewards spark brief sprints, while internal meaning drives endurance. Grounding hard daily work in personal purpose sustains momentum long after initial enthusiasm fades.',
  'Write one sentence linking today''s hardest task to the person or craft you are becoming.',
  3
),
(
  'RESILIENCE', 6, 'SELF_MANAGEMENT_DOMAIN', 'Self-Management', 'Resilience',
  'Absorbing setbacks without losing footing—extracting the lesson, regulating stress, and stepping back into action.',
  'Resilience is dynamic recovery capacity, not emotional hardness. It combines stress physiology recovery, supportive connection, and adaptive re-framing.',
  'Every meaningful goal involves friction and failure. Resilience determines whether setbacks compound into burnout or become durable learning.',
  '["Time required to regain constructive focus after disappointment.","Willingness to ask for support early.","Retention of confidence after critical feedback."]'::jsonb,
  'Resilience grows through deliberate recovery after strain: grieving or acknowledging disappointment honestly, extracting objective feedback, and stepping quickly into small forward agency.',
  'After any friction today, ask: "What is 10% within my control right now?"',
  3
)
ON CONFLICT (competency_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  domain_key = EXCLUDED.domain_key,
  domain_label = EXCLUDED.domain_label,
  title = EXCLUDED.title,
  short_content = EXCLUDED.short_content,
  what_it_is = EXCLUDED.what_it_is,
  why_it_matters = EXCLUDED.why_it_matters,
  how_to_measure = EXCLUDED.how_to_measure,
  long_content = EXCLUDED.long_content,
  practice_prompt = EXCLUDED.practice_prompt,
  estimated_read_minutes = EXCLUDED.estimated_read_minutes,
  updated_at = now();

-- ─── 2. Episode-Level Short & Long Reading Content on public.learning_content ─
ALTER TABLE public.learning_content
  ADD COLUMN IF NOT EXISTS short_content TEXT,
  ADD COLUMN IF NOT EXISTS long_content TEXT,
  ADD COLUMN IF NOT EXISTS estimated_read_minutes INT NOT NULL DEFAULT 3;

-- Populate episode-specific short_content & long_content for ALL episodes
UPDATE public.learning_content SET
  short_content = 'Affect labeling shifts brain activity from reactive alarm to deliberate appraisal—naming an emotion weakens its automatic grip.',
  long_content = 'When an intense reaction spikes in a high-stakes moment, most people stay fused with the narrative ("they are undermining me" or "this project is doomed"). Affect labeling interrupts that fusion in seconds. By tagging the precise emotional state—"I am feeling anxious about ambiguity" or "I am feeling defensive about my craft"—you create observer distance between yourself and the signal. Research in affective neuroscience shows that verbalizing specific emotional words dampens amygdala arousal and restores prefrontal clarity so your next decision reflects strategy rather than mood.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('Name it to tame it');

UPDATE public.learning_content SET
  short_content = 'Replacing reflexive reactions with real-time self-observation transforms everyday friction into clear behavioral choice.',
  long_content = 'Between routine meetings, invisible habits steer half of our tone and body language before we notice. "Mirror, Meet Mind" introduces three daily micro-checkpoints—before joining a call, after difficult feedback, and at end of day—to observe physical tension, attention drift, and unspoken assumptions without self-judgment. When you notice patterns as they happen instead of regretting them hours later, emotional triggers become neutral data points you can steer intentionally.',
  estimated_read_minutes = 3
WHERE episode_title = 'Mirror, Meet Mind';

UPDATE public.learning_content SET
  short_content = 'Equanimity under pressure comes from regulating internal nervous-system noise rather than waiting for chaotic circumstances to disappear.',
  long_content = 'Waiting for external deadlines, stakeholders, or markets to calm down guarantees chronic reactivity. Emotional balance trains you to carry steadiness inside ambiguity: slowing sensory pace, separating urgent noise from true priorities, and lowering emotional volume during escalation. When a leader maintains measured composure in turbulence, colleagues anchor to their steadiness, thinking widens, and teams solve complex problems instead of spiraling into blame.',
  estimated_read_minutes = 3
WHERE episode_title = 'Calm in the Chaos';

UPDATE public.learning_content SET
  short_content = 'Inserting a deliberate 3-to-6-second physiological pause interrupts acute impulses before regrettable words leave your mouth.',
  long_content = 'Most interpersonal damage happens inside a brief impulse window when perceived disrespect or urgency triggers a snap reply. A deliberate pause—slowing exhale cadence, dropping shoulders, and silently asking "What outcome am I actually optimizing for right now?"—gives executive reasoning time to catch up with adrenaline. Over weeks, the pause evolves from crisis control into effortless presence.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('The Pause Button');

UPDATE public.learning_content SET
  short_content = 'Strategic optimism reframes adversity as temporary data, surfacing actionable pivots where pessimism sees dead ends.',
  long_content = 'Stories lose momentum when teams conclude an obstacle marks the final chapter. Positive outlook refuses both blind cheerfulness and defeated cynicism: it zooms out to ask "What capability does this constraint force us to build now?" By treating unexpected twists as raw material for better architecture, you protect morale, preserve momentum, and convert setbacks into durable team confidence.',
  estimated_read_minutes = 3
WHERE episode_title = 'Plot Twist ; Hope Wins';

UPDATE public.learning_content SET
  short_content = 'Training your attention to log concrete progress and possibility offsets the brain''s default negativity bias during demanding quarters.',
  long_content = 'Human attention evolved to scan disproportionately for threats and defects—useful for survival, exhausting for sustained creativity. Deliberately auditing daily wins, working hypotheses, and controllable next steps rebalances attentional bandwidth without hiding real risks. Teams led by realistic optimists recover faster after misses and spot upside opportunities others miss.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Bright Side Chronicles';

UPDATE public.learning_content SET
  short_content = 'Holding goals steady while letting tactics evolve frees you from sunk-cost attachment when environments change.',
  long_content = 'Teams stall when loyalty to last quarter''s plan outweighs incoming evidence. The Art of the Pivot teaches how to distinguish enduring purpose from disposable mechanics: welcoming disconfirming metrics early, sunsetting legacy routines without ego, and reallocating focus rapidly toward emerging customer or business realities.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Art of the Pivot';

UPDATE public.learning_content SET
  short_content = 'Treating disruption as the catalyst that upgrades your capabilities converts uncertainty from threat into mastery.',
  long_content = 'Disruption tests identity: when familiar tools, structures, or expectations dissolve, discomfort is inevitable. Rather than waiting for stability to return, adaptable leaders treat every major transition as intentional skill acquisition—asking which capabilities this new chapter demands and stepping willingly into first-principles learning.',
  estimated_read_minutes = 3
WHERE episode_title = 'Change Is the Character Arc';

UPDATE public.learning_content SET
  short_content = 'Sustained excellence emerges from high standards paired with short, honest feedback loops rather than episodic perfectionism.',
  long_content = 'True achievement orientation measures craft against explicit customer impact instead of internal politics or busywork. By defining excellence upfront, inviting early critical review, and systematically refining execution cycle over cycle, teams turn ambitious targets into predictable standards.',
  estimated_read_minutes = 3
WHERE episode_title = 'Chasing Better';

UPDATE public.learning_content SET
  short_content = 'Deliberate incremental benchmarks transform intimidating long-term ambitions into compounding weekly skill upgrades.',
  long_content = 'Meaningful growth rarely arrives in a single dramatic breakthrough; it compounds through intentional micro-upgrades in preparation, precision, and follow-through. "Level Up Arc" structures daily execution into measurable stretch iterations so high performance remains sustainable without burnout.',
  estimated_read_minutes = 3
WHERE episode_title = 'Level Up Arc';

UPDATE public.learning_content SET
  short_content = 'Stepping inside another person''s emotional context turns defensive friction into shared understanding and faster problem-solving.',
  long_content = 'Misalignment across roles often stems from unspoken pressures—an engineer protecting system reliability vs. a stakeholder protecting delivery dates. Empathy pauses rebuttal long enough to mirror the other person''s stakes accurately. Once people recognize their constraints are genuinely understood, positional trench warfare dissolves into collaborative trade-offs.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('In Their Shoes');

UPDATE public.learning_content SET
  short_content = 'Attuning to emotion beneath spoken words uncovers the real blockers that purely logical debate overlooks.',
  long_content = 'Data points rarely resolve resistance when the underlying barrier is unspoken fear, status loss, or fatigue. Listening beyond surface bullet points—attending to hesitation, vocal tone, and repeated concerns—reveals what actually needs addressing so teams move forward genuinely aligned rather than silently hesitant.',
  estimated_read_minutes = 3
WHERE episode_title = 'Feel It to Get It';

UPDATE public.learning_content SET
  short_content = 'Decoding informal decision channels and hidden stakeholder priorities ensures initiatives land cleanly without late surprises.',
  long_content = 'Org charts show reporting lines, not where trust, skepticism, and real veto influence live. "Reading the Room" trains you to notice micro-reactions in cross-functional forums, diagnose unvoiced cross-department tensions, and align proposals with what sponsors actually need to succeed.',
  estimated_read_minutes = 3
WHERE episode_title = 'Reading the Room';

UPDATE public.learning_content SET
  short_content = 'Understanding cultural norms and unwritten expectations multiplies organizational effectiveness across diverse teams.',
  long_content = 'Every high-context workplace carries unwritten conventions around how dissent is voiced, how credit circulates, and how urgency is signaled. Observing these patterns respectfully—while staying anchored in integrity—helps initiatives traverse silos smoothly instead of stalling against invisible cultural friction.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Unspoken Rules';

UPDATE public.learning_content SET
  short_content = 'Anchoring proposals in your audience''s real incentives turns persuasion into voluntary ownership rather than compliance.',
  long_content = 'Pressure creates outward nodding followed by quiet drag once the meeting ends. Influence works as an invitation: researching the other person''s sharpest bottlenecks first, honoring legitimate objections openly, and co-authoring the path forward so stakeholders own the outcome voluntarily.',
  estimated_read_minutes = 3
WHERE episode_title = 'Persuasion, Not Pressure';

UPDATE public.learning_content SET
  short_content = 'Consistent integrity, preparation, and generosity build reputational pull that travels faster than formal mandates.',
  long_content = 'Quiet behavioral consistency creates trust density across teams over months. When colleagues know your evidence is rigorous, your commitments hold, and your intentions account for shared success, your voice carries outsized credibility in rooms you aren''t even sitting in.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Ripple Effect';

UPDATE public.learning_content SET
  short_content = 'Great mentors multiply capability across others by handing over judgment, feedback, and earned visibility rather than hoarding spotlight.',
  long_content = 'Leadership scale isn''t measured by how many decisions route through your inbox, but by how confidently teammates think when challenges arise. "Torchbearer" contrasts rescuing direct reports with coaching them through open inquiry, specific behavioral feedback, and supported stretch ownership.',
  estimated_read_minutes = 3
WHERE episode_title = 'Torchbearer';

UPDATE public.learning_content SET
  short_content = 'Deliberately investing in teammates'' learning creates an upward talent flywheel that strengthens retention and execution.',
  long_content = 'When development becomes shared culture rather than an annual HR checklist, peers actively trade skills, shadow tough negotiations, and elevate team benchmarks collectively. Investing time to unblock someone else''s growth expands the collective ceiling of the entire organization.',
  estimated_read_minutes = 3
WHERE episode_title = 'Growth Is Contagious';

UPDATE public.learning_content SET
  short_content = 'Constructive conflict separates personal identity from problem constraints, turning disagreements into stronger solutions.',
  long_content = 'Suppressing disagreement breeds passive-aggressive silos; personalizing disagreement breeds fear. "The Bridge Builders" demonstrates structured dialogue habits—surfacing underlying interests, checking assumptions charitably, and co-designing solutions that satisfy core requirements on both sides.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Bridge Builders';

UPDATE public.learning_content SET
  short_content = 'Addressing friction early with candor and mutual respect converts stalled relationships into resilient partnerships.',
  long_content = 'Left unaddressed, small misunderstandings compound into hardened camps. Stepping proactively into honest dialogue—"Here is the pattern I notice, here is what I respect about your goal, and here is what we need to realign"—turns sharpest tension into trust breakthroughs.',
  estimated_read_minutes = 3
WHERE episode_title = 'Tension Into Turning Point';

UPDATE public.learning_content SET
  short_content = 'Subordinating personal ego to shared mission goals raises collective standards, accountability, and speed.',
  long_content = 'Hero culture produces isolated wins alongside brittle handoffs. "We > Me" unpacks practical rituals for shared ownership: transparent risk flagging, rotating unglamorous support tasks, celebrating assists over solo credit, and measuring success by whole-team delivery.',
  estimated_read_minutes = 3
WHERE episode_title = 'We > Me';

UPDATE public.learning_content SET
  short_content = 'Timely small acts of support eliminate cross-team bottlenecks before localized delays become project failures.',
  long_content = 'Championship teams spot teammates one pass ahead of trouble. A two-minute context share, early code/doc review, or proactive unblock prevents days of downstream thrashing and fosters fierce reciprocal loyalty across departments.',
  estimated_read_minutes = 3
WHERE episode_title = 'The Assist';

UPDATE public.learning_content SET
  short_content = 'Translating strategy into crystal-clear human purpose rallies teams forward through complexity and fatigue.',
  long_content = 'Vague slogans exhaust teams quickly; crisp meaning restores energy under pressure. "Light the Way" equips leaders to connect everyday tradeoffs to tangible customer and human outcomes—giving every contributor clarity on why excellence today actually matters.',
  estimated_read_minutes = 3
WHERE episode_title = 'Light the Way';

UPDATE public.learning_content SET
  short_content = 'Steadfast belief paired with high standards gives teammates the courage to cross stretch thresholds they doubted alone.',
  long_content = 'During steep transitions, capable contributors often hesitate at the edge of unfamiliar scope. Leaders multiply potential by lending grounded confidence—naming real strengths observed in action while staying present through early stumbles until teams own that confidence themselves.',
  estimated_read_minutes = 3
WHERE episode_title = 'Borrow My Belief';

UPDATE public.learning_content SET
  short_content = 'Calibrating words around shared safety ensures difficult truths create alignment instead of defensive shutdown.',
  long_content = 'How something is framed shapes whether the listener hears curiosity or attack. "Words that land" contrasts blame-loaded phrasing with observable facts + clear impact + collaborative inquiry so important truths become hearable and actionable.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('Words that land');

UPDATE public.learning_content SET
  short_content = 'Anchoring habits in deeper personal purpose sustains discipline long after short-term willpower runs dry.',
  long_content = 'Willpower behaves like a daily battery that drains rapidly under stress and decision fatigue. Connecting demanding work to intrinsic meaning ("Why before willpower") transforms tedious discipline into deliberate identity-building effort.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('Why before willpower');

UPDATE public.learning_content SET
  short_content = 'Deliberate stress recovery and grounded reframing build measurable resilience under sustained pressure.',
  long_content = 'Resilience strengthens just like muscle tissue: intensity paired with intentional recovery. Separating controllable levers from external noise, regulating nervous-system activation, and seeking candid feedback turn inevitable setbacks into lasting adaptability.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('The Bounce Back Muscle');

UPDATE public.learning_content SET
  short_content = 'Emotional intelligence governs how perception, regulation, empathy, and communication compound across life and work.',
  long_content = 'Technical expertise opens early doors, while Emotional Intelligence determines long-term trust, clarity under stress, and leadership reach. Across four interconnected pillars—Self-Awareness, Self-Management, Social Awareness, and Relationship Management—EQ turns raw experience into repeatable wisdom.',
  estimated_read_minutes = 3
WHERE LOWER(episode_title) = LOWER('Emotional intelligence importance');

-- Safety net: ensure any future/unmatched row inherits its competency short_content & long_content
UPDATE public.learning_content lc
SET
  short_content = COALESCE(lc.short_content, g.short_content),
  long_content = COALESCE(lc.long_content, g.long_content),
  estimated_read_minutes = COALESCE(lc.estimated_read_minutes, g.estimated_read_minutes, 3)
FROM public.eq_competency_guides g
WHERE UPPER(REGEXP_REPLACE(TRIM(lc.competency), '[\s-]+', '_', 'g')) = g.competency_key
  AND (lc.short_content IS NULL OR lc.long_content IS NULL);

